      "svg": "<g class=\"el\" data-beat=\"1\"><text x=\"300\" y=\"30\" text-anchor=\"middle\" fill=\"#38bdf8\" font-size=\"18\" font-weight=\"700\">THE TAJ MAHAL VISIT</text></g><g class=\"el\" data-beat=\"2\"><circle cx=\"120\" cy=\"120\" r=\"8\" fill=\"#38bdf8\"/><circle cx=\"140\" cy=\"120\" r=\"8\" fill=\"#f472b6\"/><circle cx=\"160\" cy=\"120\" r=\"6\" fill=\"#a3e635\"/><text x=\"140\" y=\"148\" text-anchor=\"middle\" fill=\"#94a3b8\" font-size=\"11\">Family arrives at Agra</text></g><g class=\"el\" data-beat=\"3\"><rect x=\"240\" y=\"80\" width=\"120\" height=\"80\" rx=\"4\" fill=\"rgba(56,189,248,0.1)\" stroke=\"#38bdf8\" stroke-width=\"2\"/><text x=\"300\" y=\"100\" text-anchor=\"middle\" fill=\"#38bdf8\" font-size=\"11\" font-weight=\"700\">TAJ MAHAL</text><path d=\"M275 150 Q275 130 290 120 Q300 115 310 120 Q325 130 325 150 Z\" fill=\"rgba(56,189,248,0.2)\" stroke=\"#38bdf8\" stroke-width=\"1.5\"/><text x=\"300\" y=\"175\" text-anchor=\"middle\" fill=\"#94a3b8\" font-size=\"9\">First glimpse through the gateway</text></g><g class=\"el\" data-beat=\"4\"><rect x=\"100\" y=\"210\" width=\"400\" height=\"40\" rx=\"3\" fill=\"rgba(52,211,153,0.12)\" stroke=\"#34d399\" stroke-width=\"1.5\"/><text x=\"300\" y=\"235\" text-anchor=\"middle\" fill=\"#34d399\" font-size=\"11\" font-weight=\"700\">CHAR-BAGH (Four-part garden)</text><line x1=\"200\" y1=\"210\" x2=\"200\" y2=\"250\" stroke=\"#34d399\" stroke-width=\"1.5\"/><line x1=\"300\" y1=\"210\" x2=\"300\" y2=\"250\" stroke=\"#34d399\" stroke-width=\"1.5\"/><line x1=\"400\" y1=\"210\" x2=\"400\" y2=\"250\" stroke=\"#34d399\" stroke-width=\"1.5\"/><rect x=\"220\" y=\"270\" width=\"160\" height=\"14\" rx=\"2\" fill=\"rgba(56,189,248,0.35)\" stroke=\"#38bdf8\" stroke-width=\"1.5\"/><text x=\"300\" y=\"281\" text-anchor=\"middle\" fill=\"#38bdf8\" font-size=\"9\">Reflecting pool</text></g><g class=\"el\" data-beat=\"5\"><rect x=\"100\" y=\"310\" width=\"400\" height=\"70\" rx=\"6\" fill=\"rgba(244,114,182,0.12)\" stroke=\"#f472b6\" stroke-width=\"2\"/><text x=\"300\" y=\"332\" text-anchor=\"middle\" fill=\"#f472b6\" font-size=\"12\" font-weight=\"700\">PIETRA DURA INLAY</text><text x=\"300\" y=\"350\" text-anchor=\"middle\" fill=\"#e2e8f0\" font-size=\"11\">Semi-precious stones set in white marble</text><text x=\"300\" y=\"367\" text-anchor=\"middle\" fill=\"#94a3b8\" font-size=\"10\">Each flower petal is a different stone!</text></g>",
